BEGIN TRANSACTION;
CREATE TABLE audit(id INTEGER PRIMARY KEY,incident_id INTEGER REFERENCES incidents(id),actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,old_state TEXT,new_state TEXT,description TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE categories(name TEXT PRIMARY KEY);
CREATE TABLE incidents(
 id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, reporter_id INTEGER NOT NULL REFERENCES users(id),
 category TEXT NOT NULL REFERENCES categories(name), service_id INTEGER NOT NULL REFERENCES services(id),
 impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 3), urgency INTEGER NOT NULL CHECK(urgency BETWEEN 1 AND 3),
 affected_users INTEGER NOT NULL CHECK(affected_users BETWEEN 1 AND 1000000), priority TEXT NOT NULL, score INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('NEW','CLASSIFIED','ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','VERIFIED','CLOSED')),
 technician_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL, response_due TEXT NOT NULL, resolution_due TEXT NOT NULL,
 acknowledged_at TEXT, resolved_at TEXT, verified_at TEXT, closed_at TEXT, resolution TEXT NOT NULL DEFAULT '',
 feedback INTEGER CHECK(feedback BETWEEN 1 AND 5), feedback_text TEXT NOT NULL DEFAULT '',
 duplicate_of INTEGER REFERENCES incidents(id), version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE notes(id INTEGER PRIMARY KEY,incident_id INTEGER NOT NULL REFERENCES incidents(id),user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),incident_id INTEGER REFERENCES incidents(id),channel TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE services(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, criticality INTEGER NOT NULL CHECK(criticality BETWEEN 1 AND 3));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE sla_events(incident_id INTEGER NOT NULL REFERENCES incidents(id),kind TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(incident_id,kind));
CREATE TABLE sla_policies(
 service_id INTEGER REFERENCES services(id), priority TEXT NOT NULL CHECK(priority IN ('P1','P2','P3','P4')),
 response_minutes INTEGER NOT NULL CHECK(response_minutes>0), resolution_minutes INTEGER NOT NULL CHECK(resolution_minutes>=response_minutes),
 PRIMARY KEY(service_id,priority)
);
CREATE TABLE users (
 id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE,
 password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('employee','technician','admin')),
 skills TEXT NOT NULL DEFAULT '', experience INTEGER NOT NULL DEFAULT 0 CHECK(experience BETWEEN 0 AND 50),
 capacity INTEGER NOT NULL DEFAULT 5 CHECK(capacity BETWEEN 1 AND 100), available INTEGER NOT NULL DEFAULT 1,
 active INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX ix_incidents_status ON incidents(status,priority);
CREATE INDEX ix_incidents_reporter ON incidents(reporter_id);
CREATE INDEX ix_incidents_technician ON incidents(technician_id);
COMMIT;
